query:
mutation UpdateTodo($todoId: ID!, $title: String, $description: String, $status: String, $priority: String, $category: String, $dueDate: String, $completedAt: String) {
  updateNode(
    id: $todoId
    content: $title
    attributes: [
      { name: "title", value: $title }
      { name: "description", value: $description }
      { name: "status", value: $status }
      { name: "priority", value: $priority }
      { name: "category", value: $category }
      { name: "due_date", value: $dueDate }
      { name: "completed_at", value: $completedAt }
    ]
  ) {
    success
    node {
      id
      content
      attributes {
        name
        value
      }
    }
    errors {
      message
    }
  }
}
